"""Money value object — integer minor units only; no floating point."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True, slots=True)
class Money:
    """Amount in integer minor units (e.g. paise for INR)."""

    minor_units: int

    def __post_init__(self) -> None:
        if not isinstance(self.minor_units, int):
            raise TypeError("minor_units must be int")
        if isinstance(self.minor_units, bool):
            raise TypeError("minor_units must be int, not bool")
        if self.minor_units < 0:
            raise ValueError("minor_units must be non-negative")

    @classmethod
    def zero(cls) -> Money:
        return cls(0)

    def __add__(self, other: Money) -> Money:
        return Money(self.minor_units + other.minor_units)

    def __sub__(self, other: Money) -> Money:
        result = self.minor_units - other.minor_units
        if result < 0:
            raise ValueError("money subtraction would be negative")
        return Money(result)

    def __lt__(self, other: Money) -> bool:
        return self.minor_units < other.minor_units

    def __le__(self, other: Money) -> bool:
        return self.minor_units <= other.minor_units

    def __gt__(self, other: Money) -> bool:
        return self.minor_units > other.minor_units

    def __ge__(self, other: Money) -> bool:
        return self.minor_units >= other.minor_units

    @staticmethod
    def minimum(left: Money, right: Money) -> Money:
        """Return the smaller of two amounts (used in allowed / limit arithmetic)."""
        if left <= right:
            return left
        return right

import pytest

from app.domain.money import Money


def test_zero_is_non_negative() -> None:
    assert Money.zero().minor_units == 0


def test_addition() -> None:
    assert (Money(400) + Money(100)).minor_units == 500


def test_subtraction() -> None:
    assert (Money(500) - Money(100)).minor_units == 400


def test_subtraction_rejects_negative_result() -> None:
    with pytest.raises(ValueError, match="negative"):
        Money(100) - Money(200)


def test_minimum_returns_smaller_amount() -> None:
    assert Money.minimum(Money(300), Money(500)) == Money(300)
    assert Money.minimum(Money(500), Money(300)) == Money(300)


def test_rejects_negative_minor_units() -> None:
    with pytest.raises(ValueError, match="non-negative"):
        Money(-1)


def test_rejects_bool_as_minor_units() -> None:
    with pytest.raises(TypeError, match="bool"):
        Money(True)  # type: ignore[arg-type]


def test_rejects_float_as_minor_units() -> None:
    with pytest.raises(TypeError):
        Money(1.5)  # type: ignore[arg-type]


def test_money_is_immutable() -> None:
    amount = Money(100)
    with pytest.raises(AttributeError):
        amount.minor_units = 200  # type: ignore[misc]

